    && ((await shown(countCell)) !== wasCount || (await shown(diffCell)) !== wasDiff || wasCount === ''),
    page.getByTestId('rate-preview-error'), 'rate preview');
  return ok ? { count: Number(await shown(countCell)), diff: await shown(diffCell) } : null;
}

